   199→// ensureMetadataBranch creates the orphan entire/sessions branch if it doesn't exist.
   200→// This branch has no parent and starts with an empty tree.
   201→func EnsureMetadataBranch(repo *git.Repository) error {
   202→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   203→
   204→	// Check if branch already exists
   205→	_, err := repo.Reference(refName, true)
   206→	if err == nil {
   207→		// Branch already exists
   208→		return nil
   209→	}
   210→
   211→	// Create empty tree (no files)
   212→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
   213→	obj := repo.Storer.NewEncodedObject()
   214→	if err := emptyTree.Encode(obj); err != nil {
   215→		return fmt.Errorf("failed to encode empty tree: %w", err)
   216→	}
   217→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
   218→	if err != nil {
   219→		return fmt.Errorf("failed to store empty tree: %w", err)
   220→	}
   221→
   222→	// Create orphan commit (no parent)
   223→	now := time.Now()
   224→	sig := object.Signature{
   225→		Name:  "Entire",
   226→		Email: "entire@local",
   227→		When:  now,
   228→	}
   229→
   230→	commit := &object.Commit{
   231→		TreeHash:  emptyTreeHash,
   232→		Author:    sig,
   233→		Committer: sig,
   234→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata for the auto-commit strategy.\n",
   235→	}
   236→	// Note: No ParentHashes - this is an orphan commit
   237→
   238→	commitObj := repo.Storer.NewEncodedObject()
   239→	if err := commit.Encode(commitObj); err != nil {
   240→		return fmt.Errorf("failed to encode orphan commit: %w", err)
   241→	}
   242→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
   243→	if err != nil {
   244→		return fmt.Errorf("failed to store orphan commit: %w", err)
   245→	}
   246→
   247→	// Create branch reference
   248→	ref := plumbing.NewHashReference(refName, commitHash)
   249→	if err := repo.Storer.SetReference(ref); err != nil {
   250→		return fmt.Errorf("failed to create metadata branch: %w", err)
   251→	}
   252→
   253→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
   254→	return nil
   255→}
