   257→// readCheckpointMetadata reads metadata.json from a checkpoint path on entire/sessions.
   258→// With the new format, root metadata.json is a CheckpointSummary with Agents array.
   259→// This function reads the summary and extracts relevant fields into CheckpointInfo,
   260→// also reading session-level metadata for IsTask/ToolUseID fields.
   261→func ReadCheckpointMetadata(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
   262→	metadataPath := checkpointPath + "/metadata.json"
   263→	file, err := tree.File(metadataPath)
   264→	if err != nil {
   265→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
   266→	}
   267→
   268→	content, err := file.Contents()
   269→	if err != nil {
   270→		return nil, fmt.Errorf("failed to read metadata: %w", err)
   271→	}
   272→
   273→	// Try to parse as CheckpointSummary first (new format)
   274→	var summary checkpoint.CheckpointSummary
   275→	if err := json.Unmarshal([]byte(content), &summary); err == nil {
   276→		// If we have sessions array, this is the new format
   277→		if len(summary.Sessions) > 0 {
   278→			info := &CheckpointInfo{
   279→				CheckpointID:     summary.CheckpointID,
   280→				CheckpointsCount: summary.CheckpointsCount,
   281→				FilesTouched:     summary.FilesTouched,
   282→				SessionCount:     len(summary.Sessions),
   283→			}
   284→
   285→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
   286→			var sessionIDs []string
   287→			for i, sessionPaths := range summary.Sessions {
   288→				if sessionPaths.Metadata != "" {
   289→					// SessionFilePaths now contains absolute paths with leading "/"
   290→					// Strip the leading "/" for tree.File() which expects paths without leading slash
   291→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
   292→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
   293→						if sessionContent, err := sessionFile.Contents(); err == nil {
   294→							var sessionMetadata checkpoint.CommittedMetadata
   295→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   296→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
   297→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
   298→								if i == 0 {
   299→									info.Agent = sessionMetadata.Agent
   300→									info.SessionID = sessionMetadata.SessionID
   301→									info.CreatedAt = sessionMetadata.CreatedAt
   302→									info.IsTask = sessionMetadata.IsTask
   303→									info.ToolUseID = sessionMetadata.ToolUseID
   304→								}
   305→							}
   306→						}
   307→					}
   308→				}
   309→			}
   310→			info.SessionIDs = sessionIDs
   311→
   312→			return info, nil
   313→		}
   314→	}
   315→
   316→	// Fall back to parsing as CheckpointInfo (old format or direct info)
   317→	var metadata CheckpointInfo
   318→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
   319→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
   320→	}
   321→
   322→	return &metadata, nil
   323→}
