   345→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
   346→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
   347→// Returns empty string if no valid prompt is found.
   348→func ExtractFirstPrompt(content string) string {
   349→	if content == "" {
   350→		return ""
   351→	}
   352→
   353→	// Prompts are separated by "\n\n---\n\n"
   354→	// Find the first non-empty prompt
   355→	prompts := strings.Split(content, "\n\n---\n\n")
   356→	var firstPrompt string
   357→	for _, p := range prompts {
   358→		cleaned := strings.TrimSpace(p)
   359→		// Skip empty prompts or prompts that are just dashes/separators
   360→		if cleaned == "" || isOnlySeparators(cleaned) {
   361→			continue
   362→		}
   363→		firstPrompt = cleaned
   364→		break
   365→	}
   366→
   367→	if firstPrompt == "" {
   368→		return ""
   369→	}
   370→
   371→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
   372→}
