   374→// ReadSessionPromptFromTree reads the first meaningful prompt from a checkpoint's prompt.txt file in a git tree.
   375→// Returns an empty string if the prompt cannot be read.
   376→func ReadSessionPromptFromTree(tree *object.Tree, checkpointPath string) string {
   377→	promptPath := checkpointPath + "/" + paths.PromptFileName
   378→	file, err := tree.File(promptPath)
   379→	if err != nil {
   380→		return ""
   381→	}
   382→
   383→	content, err := file.Contents()
   384→	if err != nil {
   385→		return ""
   386→	}
   387→
   388→	return ExtractFirstPrompt(content)
   389→}
