   391→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
   392→func isOnlySeparators(s string) bool {
   393→	for _, r := range s {
   394→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
   395→			return false
   396→		}
   397→	}
   398→	return true
   399→}
