   401→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
   402→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
   403→// For single-session checkpoints, returns a slice with just the root prompt.
   404→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
   405→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
   406→		// Single session - just return the root prompt
   407→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
   408→		if prompt != "" {
   409→			return []string{prompt}
   410→		}
   411→		return nil
   412→	}
   413→
   414→	// Multi-session: read prompts from archived folders (0/, 1/, etc.) and root
   415→	prompts := make([]string, len(sessionIDs))
   416→
   417→	// Read archived session prompts (folders 0, 1, ... N-2)
   418→	for i := range sessionCount - 1 {
   419→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
   420→		prompts[i] = ReadSessionPromptFromTree(tree, archivedPath)
   421→	}
   422→
   423→	// Read the most recent session prompt (at root level)
   424→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
   425→
   426→	return prompts
   427→}
