   474→// OpenRepository opens the git repository with linked worktree support enabled.
   475→// It uses git.PlainOpenWithOptions with EnableDotGitCommonDir set to true,
   476→// which is required for proper operation in git worktrees created via 'git worktree add'.
   477→//
   478→// Without EnableDotGitCommonDir, go-git operations in worktrees can silently fail:
   479→// - Commits appear to succeed but are not persisted
   480→// - Refs are written to incorrect locations
   481→// - The worktree's HEAD/index don't get updated properly
   482→//
   483→// This happens because worktrees use .git as a file (pointing to the main repo)
   484→// rather than a directory, and go-git needs to route paths correctly between
   485→// shared (.git/) and per-worktree (.git/worktrees/<name>/) locations.
   486→//
   487→// The function first uses 'git rev-parse --show-toplevel' to find the repository
   488→// root, which works correctly even when called from a subdirectory within the repo.
   489→func OpenRepository() (*git.Repository, error) {
   490→	// First, find the repository root using git rev-parse --show-toplevel
   491→	// This works correctly from any subdirectory within the repository
   492→	repoRoot, err := GetWorktreePath()
   493→	if err != nil {
   494→		// Fallback to current directory if git command fails
   495→		// (e.g., if git is not installed or we're not in a repo)
   496→		repoRoot = "."
   497→	}
   498→
   499→	repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{
   500→		EnableDotGitCommonDir: true,
   501→	})
   502→	if err != nil {
   503→		return nil, fmt.Errorf("failed to open repository: %w", err)
   504→	}
   505→	return repo, nil
   506→}
   507→
   508→// IsInsideWorktree returns true if the current directory is inside a git worktree
   509→// (as opposed to the main repository). Worktrees have .git as a file pointing
   510→// to the main repo, while the main repo has .git as a directory.
   511→// This function works correctly from any subdirectory within the repository.
   512→func IsInsideWorktree() bool {
   513→	// First find the repository root
   514→	repoRoot, err := GetWorktreePath()
   515→	if err != nil {
   516→		return false
   517→	}
   518→
   519→	gitPath := filepath.Join(repoRoot, gitDir)
   520→	gitInfo, err := os.Stat(gitPath)
   521→	if err != nil {
   522→		return false
   523→	}
   524→	return !gitInfo.IsDir()
   525→}
   526→
   527→// GetMainRepoRoot returns the root directory of the main repository.
   528→// In the main repo, this is the worktree path (repo root).
   529→// In a worktree, this parses the .git file to find the main repo.
   530→// This function works correctly from any subdirectory within the repository.
   531→//
   532→// Per gitrepository-layout(5), a worktree's .git file is a "gitfile" containing
   533→// "gitdir: <path>" pointing to $GIT_DIR/worktrees/<id> in the main repository.
   534→// See: https://git-scm.com/docs/gitrepository-layout
   535→func GetMainRepoRoot() (string, error) {
   536→	// First find the worktree/repo root
   537→	repoRoot, err := GetWorktreePath()
   538→	if err != nil {
   539→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   540→	}
   541→
   542→	if !IsInsideWorktree() {
   543→		return repoRoot, nil
   544→	}
   545→
   546→	// Worktree .git file contains: "gitdir: /path/to/main/.git/worktrees/<id>"
   547→	gitFilePath := filepath.Join(repoRoot, gitDir)
   548→	content, err := os.ReadFile(gitFilePath) //nolint:gosec // G304: gitFilePath is constructed from repo root, not user input
   549→	if err != nil {
   550→		return "", fmt.Errorf("failed to read .git file: %w", err)
   551→	}
   552→
   553→	gitdir := strings.TrimSpace(string(content))
   554→	gitdir = strings.TrimPrefix(gitdir, "gitdir: ")
   555→
   556→	// Extract main repo root: everything before "/.git/"
   557→	idx := strings.LastIndex(gitdir, "/.git/")
   558→	if idx < 0 {
   559→		return "", fmt.Errorf("unexpected gitdir format: %s", gitdir)
   560→	}
   561→	return gitdir[:idx], nil
   562→}
   563→
   564→// GetGitCommonDir returns the path to the shared git directory.
   565→// In a regular checkout, this is .git/
   566→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
   567→// Uses git rev-parse --git-common-dir for reliable handling of worktrees.
   568→func GetGitCommonDir() (string, error) {
   569→	ctx := context.Background()
   570→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
   571→	cmd.Dir = "."
   572→	output, err := cmd.Output()
   573→	if err != nil {
   574→		return "", fmt.Errorf("failed to get git common dir: %w", err)
   575→	}
   576→
   577→	commonDir := strings.TrimSpace(string(output))
   578→
   579→	// git rev-parse --git-common-dir returns relative paths from the working directory,
   580→	// so we need to make it absolute if it isn't already
   581→	if !filepath.IsAbs(commonDir) {
   582→		commonDir = filepath.Join(".", commonDir)
   583→	}
   584→
   585→	return filepath.Clean(commonDir), nil
   586→}
   587→
   588→// GetWorktreePath returns the absolute path to the current worktree root.
   589→// This is the working directory path, not the git directory.
   590→func GetWorktreePath() (string, error) {
   591→	ctx := context.Background()
   592→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
   593→	output, err := cmd.Output()
   594→	if err != nil {
   595→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   596→	}
   597→	return strings.TrimSpace(string(output)), nil
   598→}
