   600→// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
   601→// Works correctly from any subdirectory within the repository.
   602→func EnsureEntireGitignore() error {
   603→	// Get absolute path for the gitignore file
   604→	gitignoreAbs, err := paths.AbsPath(entireGitignore)
   605→	if err != nil {
   606→		gitignoreAbs = entireGitignore // Fallback to relative
   607→	}
   608→
   609→	// Read existing content
   610→	var content string
   611→	if data, err := os.ReadFile(gitignoreAbs); err == nil { //nolint:gosec // path is from AbsPath or constant
   612→		content = string(data)
   613→	}
   614→
   615→	// All entries that should be in .entire/.gitignore
   616→	requiredEntries := []string{
   617→		"tmp/",
   618→		"settings.local.json",
   619→		"metadata/",
   620→		"current_session",
   621→		"logs/",
   622→	}
   623→
   624→	// Track what needs to be added
   625→	var toAdd []string
   626→	for _, entry := range requiredEntries {
   627→		if !strings.Contains(content, entry) {
   628→			toAdd = append(toAdd, entry)
   629→		}
   630→	}
   631→
   632→	// Nothing to add
   633→	if len(toAdd) == 0 {
   634→		return nil
   635→	}
   636→
   637→	// Ensure .entire directory exists
   638→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
   639→		return fmt.Errorf("failed to create .entire directory: %w", err)
   640→	}
   641→
   642→	// Append missing entries to gitignore
   643→	var sb strings.Builder
   644→	for _, entry := range toAdd {
   645→		sb.WriteString(entry + "\n")
   646→	}
   647→	content += sb.String()
   648→
   649→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
   650→		return fmt.Errorf("failed to write gitignore: %w", err)
   651→	}
   652→	return nil
   653→}
