   655→// checkCanRewind checks if working directory is clean enough for rewind.
   656→// Returns (canRewind, reason, error). Shared by shadow and linear-shadow strategies.
   657→func checkCanRewind() (bool, string, error) {
   658→	repo, err := OpenRepository()
   659→	if err != nil {
   660→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
   661→	}
   662→
   663→	status, err := gitutil.WorktreeStatus(repo)
   664→	if err != nil {
   665→		return false, "", fmt.Errorf("failed to get status: %w", err)
   666→	}
   667→
   668→	if status.IsClean() {
   669→		return true, "", nil
   670→	}
   671→
   672→	var modified, added, deleted []string
   673→	for file, st := range status {
   674→		// Skip .entire directory
   675→		if paths.IsInfrastructurePath(file) {
   676→			continue
   677→		}
   678→
   679→		// Skip untracked files
   680→		if st.Worktree == git.Untracked {
   681→			continue
   682→		}
   683→
   684→		switch {
   685→		case st.Staging == git.Added || st.Worktree == git.Added:
   686→			added = append(added, file)
   687→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
   688→			deleted = append(deleted, file)
   689→		case st.Staging == git.Modified || st.Worktree == git.Modified:
   690→			modified = append(modified, file)
   691→		}
   692→	}
   693→
   694→	if len(modified) == 0 && len(added) == 0 && len(deleted) == 0 {
   695→		return true, "", nil
   696→	}
   697→
   698→	var msg strings.Builder
   699→	msg.WriteString("You have uncommitted changes:\n")
   700→	for _, f := range modified {
   701→		msg.WriteString(fmt.Sprintf("  modified:   %s\n", f))
   702→	}
   703→	for _, f := range added {
   704→		msg.WriteString(fmt.Sprintf("  added:      %s\n", f))
   705→	}
   706→	for _, f := range deleted {
   707→		msg.WriteString(fmt.Sprintf("  deleted:    %s\n", f))
   708→	}
   709→	msg.WriteString("\nPlease commit or stash your changes before rewinding.")
   710→
   711→	return false, msg.String(), nil
   712→}
