   714→// checkCanRewindWithWarning checks working directory and returns a warning with diff stats.
   715→// Unlike checkCanRewind, this always returns canRewind=true but includes a warning message
   716→// with +/- line stats for uncommitted changes. Used by manual-commit strategy.
   717→func checkCanRewindWithWarning() (bool, string, error) {
   718→	repo, err := OpenRepository()
   719→	if err != nil {
   720→		// Can't open repo - still allow rewind but without stats
   721→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo can't be opened
   722→	}
   723→
   724→	status, err := gitutil.WorktreeStatus(repo)
   725→	if err != nil {
   726→		return true, "", nil //nolint:nilerr // Rewind allowed even if status can't be retrieved
   727→	}
   728→
   729→	if status.IsClean() {
   730→		return true, "", nil
   731→	}
   732→
   733→	// Get HEAD commit tree for comparison - if we can't get it, just return without stats
   734→	head, err := repo.Head()
   735→	if err != nil {
   736→		return true, "", nil //nolint:nilerr // Rewind allowed even without HEAD (e.g., empty repo)
   737→	}
   738→
   739→	headCommit, err := repo.CommitObject(head.Hash())
   740→	if err != nil {
   741→		return true, "", nil //nolint:nilerr // Rewind allowed even if commit lookup fails
   742→	}
   743→
   744→	headTree, err := headCommit.Tree()
   745→	if err != nil {
   746→		return true, "", nil //nolint:nilerr // Rewind allowed even if tree lookup fails
   747→	}
   748→
   749→	type fileChange struct {
   750→		status   string // "modified", "added", "deleted"
   751→		added    int
   752→		removed  int
   753→		filename string
   754→	}
   755→
   756→	var changes []fileChange
   757→	// Use repo root, not cwd - git status returns paths relative to repo root
   758→	repoRoot, err := GetWorktreePath()
   759→	if err != nil {
   760→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo root lookup fails
   761→	}
   762→
   763→	for file, st := range status {
   764→		// Skip .entire directory
   765→		if paths.IsInfrastructurePath(file) {
   766→			continue
   767→		}
   768→
   769→		// Skip untracked files
   770→		if st.Worktree == git.Untracked {
   771→			continue
   772→		}
   773→
   774→		var change fileChange
   775→		change.filename = file
   776→
   777→		switch {
   778→		case st.Staging == git.Added || st.Worktree == git.Added:
   779→			change.status = "added"
   780→			// New file - count all lines as added
   781→			absPath := filepath.Join(repoRoot, file)
   782→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
   783→				change.added = countLines(content)
   784→			}
   785→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
   786→			change.status = "deleted"
   787→			// Deleted file - count lines from HEAD as removed
   788→			if entry, err := headTree.File(file); err == nil {
   789→				if content, err := entry.Contents(); err == nil {
   790→					change.removed = countLines([]byte(content))
   791→				}
   792→			}
   793→		case st.Staging == git.Modified || st.Worktree == git.Modified:
   794→			change.status = "modified"
   795→			// Modified file - compute diff stats
   796→			var headContent, workContent []byte
   797→			if entry, err := headTree.File(file); err == nil {
   798→				if content, err := entry.Contents(); err == nil {
   799→					headContent = []byte(content)
   800→				}
   801→			}
   802→			absPath := filepath.Join(repoRoot, file)
   803→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
   804→				workContent = content
   805→			}
   806→			if headContent != nil && workContent != nil {
   807→				change.added, change.removed = computeDiffStats(headContent, workContent)
   808→			}
   809→		default:
   810→			continue
   811→		}
   812→
   813→		changes = append(changes, change)
   814→	}
   815→
   816→	if len(changes) == 0 {
   817→		return true, "", nil
   818→	}
   819→
   820→	// Sort changes by filename for consistent output
   821→	sort.Slice(changes, func(i, j int) bool {
   822→		return changes[i].filename < changes[j].filename
   823→	})
   824→
   825→	var msg strings.Builder
   826→	msg.WriteString("The following uncommitted changes will be reverted:\n")
   827→
   828→	totalAdded, totalRemoved := 0, 0
   829→	for _, c := range changes {
   830→		totalAdded += c.added
   831→		totalRemoved += c.removed
   832→
   833→		var stats string
   834→		switch {
   835→		case c.added > 0 && c.removed > 0:
   836→			stats = fmt.Sprintf("+%d/-%d", c.added, c.removed)
   837→		case c.added > 0:
   838→			stats = fmt.Sprintf("+%d", c.added)
   839→		case c.removed > 0:
   840→			stats = fmt.Sprintf("-%d", c.removed)
   841→		}
   842→
   843→		msg.WriteString(fmt.Sprintf("  %-10s %s", c.status+":", c.filename))
   844→		if stats != "" {
   845→			msg.WriteString(fmt.Sprintf(" (%s)", stats))
   846→		}
   847→		msg.WriteString("\n")
   848→	}
   849→
   850→	if totalAdded > 0 || totalRemoved > 0 {
   851→		msg.WriteString(fmt.Sprintf("\nTotal: +%d/-%d lines\n", totalAdded, totalRemoved))
   852→	}
   853→
   854→	return true, msg.String(), nil
   855→}
