   857→// countLines counts the number of lines in content.
   858→func countLines(content []byte) int {
   859→	if len(content) == 0 {
   860→		return 0
   861→	}
   862→	count := 1
   863→	for _, b := range content {
   864→		if b == '\n' {
   865→			count++
   866→		}
   867→	}
   868→	// Don't count trailing newline as extra line
   869→	if len(content) > 0 && content[len(content)-1] == '\n' {
   870→		count--
   871→	}
   872→	return count
   873→}
   874→
   875→// computeDiffStats computes added and removed line counts between old and new content.
   876→// Uses a simple line-based diff algorithm.
   877→func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
   878→	oldLines := splitLines(oldContent)
   879→	newLines := splitLines(newContent)
   880→
   881→	// Build a set of old lines with counts
   882→	oldSet := make(map[string]int)
   883→	for _, line := range oldLines {
   884→		oldSet[line]++
   885→	}
   886→
   887→	// Check which new lines are truly new
   888→	for _, line := range newLines {
   889→		if oldSet[line] > 0 {
   890→			oldSet[line]--
   891→		} else {
   892→			added++
   893→		}
   894→	}
   895→
   896→	// Remaining old lines are removed
   897→	for _, count := range oldSet {
   898→		removed += count
   899→	}
   900→
   901→	return added, removed
   902→}
   903→
   904→// splitLines splits content into lines, preserving empty lines.
   905→func splitLines(content []byte) []string {
   906→	if len(content) == 0 {
   907→		return nil
   908→	}
   909→	s := string(content)
   910→	// Remove trailing newline to avoid empty last element
   911→	s = strings.TrimSuffix(s, "\n")
   912→	return strings.Split(s, "\n")
   913→}
