   921→// StageFilesContext describes what type of staging operation this is (for messages).
   922→type StageFilesContext string
   923→
   924→const (
   925→	// StageForSession is used when staging files for a session checkpoint.
   926→	StageForSession StageFilesContext = "session"
   927→	// StageForTask is used when staging files for a task checkpoint.
   928→	StageForTask StageFilesContext = "task"
   929→)
