   931→// StageFiles stages modified, new, and deleted files to the git worktree.
   932→//
   933→// This function handles three categories of file changes:
   934→//  1. Modified files: existing files that have been changed
   935→//  2. New files: files that were created during the session
   936→//  3. Deleted files: files that were removed during the session
   937→//
   938→// Error Handling Strategy:
   939→//   - Individual file staging errors are logged to stderr but don't fail the operation
   940→//   - This ensures that partial staging succeeds even if some files have issues
   941→//   - If a modified file no longer exists, it's treated as a deletion
   942→//
   943→// The stageCtx parameter is used for user-facing messages to indicate whether
   944→// this is staging for a session checkpoint or a task checkpoint.
   945→func StageFiles(worktree *git.Worktree, modified, newFiles, deleted []string, stageCtx StageFilesContext) {
   946→	// Get repo root for resolving file paths
   947→	// This is critical because fileExists() uses os.Stat() which resolves relative to CWD,
   948→	// but worktree.Add/Remove resolve relative to repo root. If CWD != repo root,
   949→	// fileExists() could return false for existing files, causing worktree.Remove()
   950→	// to incorrectly delete them.
   951→	repoRoot := worktree.Filesystem.Root()
   952→
   953→	// Stage modified files
   954→	for _, file := range modified {
   955→		// Resolve path relative to repo root for existence check
   956→		absPath := filepath.Join(repoRoot, file)
   957→		if fileExists(absPath) {
   958→			if _, err := worktree.Add(file); err != nil {
   959→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
   960→			} else {
   961→				fmt.Fprintf(os.Stderr, "  Staged: %s\n", file)
   962→			}
   963→		} else {
   964→			// File was deleted - stage the deletion
   965→			if _, err := worktree.Remove(file); err != nil {
   966→				fmt.Fprintf(os.Stderr, "  File not found or deleted: %s\n", file)
   967→			}
   968→		}
   969→	}
   970→
   971→	// Stage new files
   972→	if len(newFiles) > 0 {
   973→		fmt.Fprintf(os.Stderr, "Staging %d new files created during %s:\n", len(newFiles), stageCtx)
   974→		for _, file := range newFiles {
   975→			if _, err := worktree.Add(file); err != nil {
   976→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
   977→			} else {
   978→				fmt.Fprintf(os.Stderr, "  Staged new file: %s\n", file)
   979→			}
   980→		}
   981→	}
   982→
   983→	// Stage deleted files
   984→	for _, file := range deleted {
   985→		if _, err := worktree.Remove(file); err != nil {
   986→			fmt.Fprintf(os.Stderr, "  Failed to stage deleted file %s: %v\n", file, err)
   987→		} else {
   988→			fmt.Fprintf(os.Stderr, "  Staged deleted file: %s\n", file)
   989→		}
   990→	}
   991→}
