   996→	if !point.IsTaskCheckpoint {
   997→		return nil, ErrNotTaskCheckpoint
   998→	}
   999→
  1000→	repo, err := OpenRepository()
  1001→	if err != nil {
  1002→		return nil, fmt.Errorf("failed to open repository: %w", err)
  1003→	}
  1004→
  1005→	commitHash := plumbing.NewHash(point.ID)
  1006→	commit, err := repo.CommitObject(commitHash)
  1007→	if err != nil {
  1008→		return nil, fmt.Errorf("failed to get commit: %w", err)
  1009→	}
  1010→
  1011→	tree, err := commit.Tree()
  1012→	if err != nil {
  1013→		return nil, fmt.Errorf("failed to get tree: %w", err)
  1014→	}
  1015→
  1016→	// Read checkpoint.json from the tree
  1017→	checkpointPath := point.MetadataDir + "/checkpoint.json"
