  1027→
  1028→	var checkpoint TaskCheckpoint
  1029→	if err := json.Unmarshal([]byte(content), &checkpoint); err != nil {
  1030→		return nil, fmt.Errorf("failed to parse checkpoint: %w", err)
  1031→	}
  1032→
  1033→	return &checkpoint, nil
  1034→}
