  1082→// HardResetWithProtection performs a git reset --hard to the specified commit.
  1083→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
  1084→// deletes untracked directories (like .entire/) even when they're in .gitignore.
  1085→// Returns the short commit ID (7 chars) on success for display purposes.
  1086→func HardResetWithProtection(commitHash plumbing.Hash) (shortID string, err error) {
  1087→	ctx := context.Background()
  1088→	hashStr := commitHash.String()
  1089→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr) //nolint:gosec // hashStr is a plumbing.Hash, not user input
  1090→	if output, err := cmd.CombinedOutput(); err != nil {
  1091→		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
  1092→	}
  1093→
  1094→	// Return short commit ID for display
  1095→	shortID = hashStr
  1096→	if len(shortID) > 7 {
  1097→		shortID = shortID[:7]
  1098→	}
  1099→	return shortID, nil
  1100→}
