  1102→// collectUntrackedFiles collects all untracked files in the working directory.
  1103→// This is used to capture the initial state when starting a session,
  1104→// ensuring untracked files present at session start are preserved during rewind.
  1105→// Excludes .git/, .entire/, and .claude/ directories (which are system/config directories).
  1106→// Works correctly from any subdirectory within the repository.
  1107→func collectUntrackedFiles() ([]string, error) {
  1108→	// Get repository root to walk from there
  1109→	repoRoot, err := GetWorktreePath()
  1110→	if err != nil {
  1111→		repoRoot = "." // Fallback to current directory
  1112→	}
  1113→
  1114→	var untrackedFiles []string
  1115→	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
  1116→		if walkErr != nil {
  1117→			return nil //nolint:nilerr // Skip filesystem errors during walk
  1118→		}
  1119→
  1120→		// Get path relative to repo root
  1121→		relPath, err := filepath.Rel(repoRoot, path)
  1122→		if err != nil {
  1123→			return nil //nolint:nilerr // Skip paths we can't make relative
  1124→		}
  1125→
  1126→		// Skip directories
  1127→		if info.IsDir() {
  1128→			// Skip .git, .claude, and .entire directories
  1129→			if relPath == gitDir || relPath == claudeDir || relPath == entireDir ||
  1130→				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
  1131→				return filepath.SkipDir
  1132→			}
  1133→			return nil
  1134→		}
  1135→
  1136→		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
  1137→		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
  1138→			return nil
  1139→		}
  1140→
  1141→		untrackedFiles = append(untrackedFiles, relPath)
  1142→		return nil
  1143→	})
  1144→	if err != nil {
  1145→		return nil, fmt.Errorf("failed to walk directory: %w", err)
  1146→	}
  1147→
  1148→	return untrackedFiles, nil
  1149→}
