  1151→// ExtractSessionIDFromCommit extracts the session ID from a commit's trailers.
  1152→// It checks the Entire-Session trailer first, then falls back to extracting from
  1153→// the metadata directory path in the Entire-Metadata trailer.
  1154→// Returns empty string if no session ID is found.
  1155→func ExtractSessionIDFromCommit(commit *object.Commit) string {
  1156→	// Try Entire-Session trailer first
  1157→	if sessionID, found := trailers.ParseSession(commit.Message); found {
  1158→		return sessionID
  1159→	}
  1160→
  1161→	// Try extracting from metadata directory (last path component)
  1162→	if metadataDir, found := trailers.ParseMetadata(commit.Message); found {
  1163→		return filepath.Base(metadataDir)
  1164→	}
  1165→
  1166→	return ""
  1167→}
