  1170→// - FlattenTree -> checkpoint.FlattenTree
  1171→// - CreateBlobFromContent -> checkpoint.CreateBlobFromContent
  1172→// - BuildTreeFromEntries -> checkpoint.BuildTreeFromEntries
  1173→// - sortTreeEntries (internal to checkpoint package)
