  1177→
  1178→// createCommit creates a commit object
  1179→func createCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
  1180→	now := time.Now()
  1181→	sig := object.Signature{
  1182→		Name:  authorName,
  1183→		Email: authorEmail,
  1184→		When:  now,
  1185→	}
  1186→
  1187→	commit := &object.Commit{
  1188→		TreeHash:  treeHash,
  1189→		Author:    sig,
  1190→		Committer: sig,
  1191→		Message:   message,
  1192→	}
  1193→
  1194→	// Add parent if not a new branch
  1195→	if parentHash != plumbing.ZeroHash {
  1196→		commit.ParentHashes = []plumbing.Hash{parentHash}
  1197→	}
  1198→
  1199→	obj := repo.Storer.NewEncodedObject()
  1200→	if err := commit.Encode(obj); err != nil {
  1201→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
  1202→	}
  1203→
  1204→	hash, err := repo.Storer.SetEncodedObject(obj)
  1205→	if err != nil {
  1206→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
  1207→	}
  1208→
  1209→	return hash, nil
  1210→}
