  1212→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
  1213→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
  1214→//
  1215→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
  1216→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
  1217→// the session directory, e.g., auto-commit strategy's sharded metadata), then falls back to
  1218→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
  1219→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
  1220→	// Helper to read first line from a file in tree
  1221→	readFirstLine := func(path string) string {
  1222→		file, err := tree.File(path)
  1223→		if err != nil {
  1224→			return ""
  1225→		}
  1226→		content, err := file.Contents()
  1227→		if err != nil {
  1228→			return ""
  1229→		}
  1230→		lines := strings.SplitN(content, "\n", 2)
  1231→		if len(lines) > 0 && lines[0] != "" {
  1232→			desc := strings.TrimSpace(lines[0])
  1233→			// Remove markdown header prefix if present
  1234→			return strings.TrimPrefix(desc, "# ")
  1235→		}
  1236→		return ""
  1237→	}
  1238→
  1239→	// If metadataDir is provided, look there directly
  1240→	if metadataDir != "" {
  1241→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
  1242→			return desc
  1243→		}
  1244→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
  1245→			return desc
  1246→		}
  1247→		return NoDescription
  1248→	}
  1249→
  1250→	// No metadataDir provided - first try looking at the root of the tree
  1251→	// (used when the tree is already the session directory)
  1252→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
  1253→		return desc
  1254→	}
  1255→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
  1256→		return desc
  1257→	}
  1258→
  1259→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
  1260→	// (used when the tree is the full worktree)
  1261→	var desc string
  1262→	//nolint:errcheck // We ignore errors here as we're just searching for a description
  1263→	_ = tree.Files().ForEach(func(f *object.File) error {
  1264→		if desc != "" {
  1265→			return nil // Already found description
  1266→		}
  1267→		name := f.Name
  1268→		if strings.Contains(name, ".entire/metadata/") {
  1269→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
  1270→				content, err := f.Contents()
  1271→				if err != nil {
  1272→					return nil //nolint:nilerr // Skip files we can't read, continue searching
  1273→				}
  1274→				lines := strings.SplitN(content, "\n", 2)
  1275→				if len(lines) > 0 && lines[0] != "" {
  1276→					desc = strings.TrimSpace(lines[0])
  1277→					desc = strings.TrimPrefix(desc, "# ")
  1278→				}
  1279→			}
  1280→		}
  1281→		return nil
  1282→	})
  1283→
  1284→	if desc != "" {
  1285→		return desc
  1286→	}
  1287→	return NoDescription
  1288→}
