  1290→// GetGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1291→// It checks local config first, then falls back to global config.
  1292→// Returns ("Unknown", "unknown@local") if no user is configured - this allows
  1293→// operations to proceed even without git user config, which is especially useful
  1294→// for internal metadata commits on branches like entire/sessions.
  1295→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1296→	// Get repository config (includes local settings)
  1297→	cfg, err := repo.Config()
  1298→	if err == nil {
  1299→		name = cfg.User.Name
  1300→		email = cfg.User.Email
  1301→	}
  1302→
  1303→	// If not found in local config, try global config
  1304→	if name == "" || email == "" {
  1305→		globalCfg, err := config.LoadConfig(config.GlobalScope)
  1306→		if err == nil {
  1307→			if name == "" {
  1308→				name = globalCfg.User.Name
  1309→			}
  1310→			if email == "" {
  1311→				email = globalCfg.User.Email
  1312→			}
  1313→		}
  1314→	}
  1315→
  1316→	// Provide sensible defaults if git user is not configured
  1317→	if name == "" {
  1318→		name = "Unknown"
  1319→	}
  1320→	if email == "" {
  1321→		email = "unknown@local"
  1322→	}
  1323→
  1324→	return name, email
  1325→}
