  1327→// GetCurrentBranchName returns the short name of the current branch if HEAD points to a branch.
  1328→// Returns an empty string if in detached HEAD state or if there's an error reading HEAD.
  1329→// This is used to capture branch metadata for checkpoints.
  1330→func GetCurrentBranchName(repo *git.Repository) string {
  1331→	head, err := repo.Head()
  1332→	if err != nil || !head.Name().IsBranch() {
  1333→		return ""
  1334→	}
  1335→	return head.Name().Short()
  1336→}
