  1338→// getMainBranchHash returns the hash of the main branch (main or master).
  1339→// Returns ZeroHash if no main branch is found.
  1340→func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
  1341→	// Try common main branch names
  1342→	for _, branchName := range []string{branchMain, branchMaster} {
  1343→		// Try local branch first
  1344→		ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
  1345→		if err == nil {
  1346→			return ref.Hash()
  1347→		}
  1348→		// Try remote tracking branch
  1349→		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
  1350→		if err == nil {
  1351→			return ref.Hash()
  1352→		}
  1353→	}
  1354→	return plumbing.ZeroHash
  1355→}
