  1357→// GetDefaultBranchName returns the name of the default branch.
  1358→// First checks origin/HEAD, then falls back to checking if main/master exists.
  1359→// Returns empty string if unable to determine.
  1360→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1361→func GetDefaultBranchName(repo *git.Repository) string {
  1362→	// Try to get the symbolic reference for origin/HEAD
  1363→	// Use resolved=false to get the symbolic ref itself, then extract its target
  1364→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), false)
  1365→	if err == nil && ref != nil && ref.Type() == plumbing.SymbolicReference {
  1366→		target := ref.Target().String()
  1367→		if branchName, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
  1368→			return branchName
  1369→		}
  1370→	}
  1371→
  1372→	// Fallback: check if origin/main or origin/master exists
  1373→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMain), true); err == nil {
  1374→		return branchMain
  1375→	}
  1376→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMaster), true); err == nil {
  1377→		return branchMaster
  1378→	}
  1379→
  1380→	// Final fallback: check local branches
  1381→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMain), true); err == nil {
  1382→		return branchMain
  1383→	}
  1384→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMaster), true); err == nil {
  1385→		return branchMaster
  1386→	}
  1387→
  1388→	return ""
  1389→}
  1390→
  1391→// IsOnDefaultBranch checks if the repository HEAD is on the default branch.
  1392→// Returns (isOnDefault, currentBranchName).
  1393→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1394→func IsOnDefaultBranch(repo *git.Repository) (bool, string) {
  1395→	currentBranch := GetCurrentBranchName(repo)
  1396→	if currentBranch == "" {
  1397→		return false, ""
  1398→	}
  1399→
  1400→	defaultBranch := GetDefaultBranchName(repo)
  1401→	if defaultBranch == "" {
  1402→		// Can't determine default, check common names
  1403→		if currentBranch == branchMain || currentBranch == branchMaster {
  1404→			return true, currentBranch
  1405→		}
  1406→		return false, currentBranch
  1407→	}
  1408→
  1409→	return currentBranch == defaultBranch, currentBranch
  1410→}
