    37→// CapturePrePromptState captures current untracked files and transcript position before a prompt
    38→// and saves them to a state file.
    39→// Works correctly from any subdirectory within the repository.
    40→// The transcriptPath parameter is optional - if empty, transcript position won't be captured.
    41→func CapturePrePromptState(sessionID, transcriptPath string) error {
    42→	if sessionID == "" {
    43→		sessionID = unknownSessionID
    44→	}
    45→
    46→	// Get absolute path for tmp directory
    47→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
    48→	if err != nil {
    49→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
    50→	}
    51→
    52→	// Create tmp directory if it doesn't exist
    53→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
    54→		return fmt.Errorf("failed to create tmp directory: %w", err)
    55→	}
    56→
    57→	// Get list of untracked files (excluding .entire directory itself)
    58→	untrackedFiles, err := getUntrackedFilesForState()
    59→	if err != nil {
    60→		return fmt.Errorf("failed to get untracked files: %w", err)
    61→	}
    62→
    63→	// Get transcript position (last UUID and line count)
    64→	var transcriptPos TranscriptPosition
    65→	if transcriptPath != "" {
    66→		transcriptPos, err = GetTranscriptPosition(transcriptPath)
    67→		if err != nil {
    68→			// Log warning but don't fail - transcript position is optional
    69→			fmt.Fprintf(os.Stderr, "Warning: failed to get transcript position: %v\n", err)
    70→		}
    71→	}
    72→
    73→	// Create state file
    74→	stateFile := prePromptStateFile(sessionID)
    75→	state := PrePromptState{
    76→		SessionID:                sessionID,
    77→		Timestamp:                time.Now().UTC().Format(time.RFC3339),
    78→		UntrackedFiles:           untrackedFiles,
    79→		LastTranscriptIdentifier: transcriptPos.LastUUID,
    80→		LastTranscriptLineCount:  transcriptPos.LineCount,
    81→	}
    82→
    83→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
    84→	if err != nil {
    85→		return fmt.Errorf("failed to marshal state: %w", err)
    86→	}
    87→
    88→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
    89→		return fmt.Errorf("failed to write state file: %w", err)
    90→	}
    91→
    92→	fmt.Fprintf(os.Stderr, "Captured state before prompt: %d untracked files, transcript at line %d (uuid: %s)\n",
    93→		len(untrackedFiles), transcriptPos.LineCount, transcriptPos.LastUUID)
    94→	return nil
    95→}
