    97→// CaptureGeminiPrePromptState captures current untracked files and transcript position
    98→// before a prompt for Gemini sessions. This is called by the BeforeAgent hook.
    99→// The transcriptPath is the path to the Gemini session transcript (JSON format).
   100→func CaptureGeminiPrePromptState(sessionID, transcriptPath string) error {
   101→	if sessionID == "" {
   102→		sessionID = unknownSessionID
   103→	}
   104→
   105→	// Get absolute path for tmp directory
   106→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   107→	if err != nil {
   108→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   109→	}
   110→
   111→	// Create tmp directory if it doesn't exist
   112→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
   113→		return fmt.Errorf("failed to create tmp directory: %w", err)
   114→	}
   115→
   116→	// Get list of untracked files (excluding .entire directory itself)
   117→	untrackedFiles, err := getUntrackedFilesForState()
   118→	if err != nil {
   119→		return fmt.Errorf("failed to get untracked files: %w", err)
   120→	}
   121→
   122→	// Get transcript position (message count and last message ID) for Gemini
   123→	var startMessageIndex int
   124→	var lastMessageID string
   125→	if transcriptPath != "" {
   126→		// Read transcript and extract both message count and last message ID
   127→		if data, readErr := os.ReadFile(transcriptPath); readErr == nil && len(data) > 0 { //nolint:gosec // Reading from controlled transcript path
   128→			var transcript struct {
   129→				Messages []struct {
   130→					ID string `json:"id"`
   131→				} `json:"messages"`
   132→			}
   133→			if jsonErr := json.Unmarshal(data, &transcript); jsonErr == nil {
   134→				startMessageIndex = len(transcript.Messages)
   135→				if startMessageIndex > 0 {
   136→					lastMessageID = transcript.Messages[startMessageIndex-1].ID
   137→				}
   138→			} else {
   139→				fmt.Fprintf(os.Stderr, "Warning: failed to parse transcript for message tracking: %v\n", jsonErr)
   140→			}
   141→		}
   142→	}
   143→
   144→	// Create state file
   145→	stateFile := prePromptStateFile(sessionID)
   146→	state := PrePromptState{
   147→		SessionID:                sessionID,
   148→		Timestamp:                time.Now().UTC().Format(time.RFC3339),
   149→		UntrackedFiles:           untrackedFiles,
   150→		StartMessageIndex:        startMessageIndex,
   151→		LastTranscriptIdentifier: lastMessageID,
   152→	}
   153→
   154→	data, err := json.MarshalIndent(state, "", "  ")
   155→	if err != nil {
   156→		return fmt.Errorf("failed to marshal state: %w", err)
   157→	}
   158→
   159→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
   160→		return fmt.Errorf("failed to write state file: %w", err)
   161→	}
   162→
   163→	fmt.Fprintf(os.Stderr, "Captured Gemini state before prompt: %d untracked files, transcript position: %d (last msg id: %s)\n", len(untrackedFiles), startMessageIndex, lastMessageID)
   164→	return nil
   165→}
