   198→// ComputeFileChanges returns new files (created during session) and deleted files
   199→// (tracked files that were deleted) using a single git status call.
   200→// This is more efficient than calling ComputeNewFiles and ComputeDeletedFiles separately.
   201→//
   202→// If preState is nil, newFiles will be nil but deletedFiles will still be computed
   203→// (deleted files don't depend on pre-prompt state).
   204→func ComputeFileChanges(preState *PrePromptState) (newFiles, deletedFiles []string, err error) {
   205→	repo, err := openRepository()
   206→	if err != nil {
   207→		return nil, nil, err
   208→	}
   209→
   210→	status, err := gitutil.WorktreeStatus(repo)
   211→	if err != nil {
   212→		return nil, nil, fmt.Errorf("failed to get status: %w", err)
   213→	}
   214→
   215→	// Build set of pre-existing untracked files for quick lookup (only if preState exists)
   216→	var preExisting map[string]bool
   217→	if preState != nil {
   218→		preExisting = make(map[string]bool, len(preState.UntrackedFiles))
   219→		for _, f := range preState.UntrackedFiles {
   220→			preExisting[f] = true
   221→		}
   222→	}
   223→
   224→	// Process all files from git status
   225→	for file, st := range status {
   226→		// Skip .entire directory
   227→		if paths.IsInfrastructurePath(file) {
   228→			continue
   229→		}
   230→
   231→		switch {
   232→		case st.Worktree == git.Untracked && preState != nil:
   233→			// New file if it wasn't untracked before the session
   234→			// (only compute if we have preState to compare against)
   235→			if !preExisting[file] {
   236→				newFiles = append(newFiles, file)
   237→			}
   238→		case st.Worktree == git.Deleted && st.Staging != git.Deleted:
   239→			// Deleted file (tracked file that was deleted, not yet staged)
   240→			deletedFiles = append(deletedFiles, file)
   241→		}
   242→	}
   243→
   244→	return newFiles, deletedFiles, nil
   245→}
