   295→// FilterAndNormalizePaths converts absolute paths to relative and filters out
   296→// infrastructure paths and paths outside the repo.
   297→func FilterAndNormalizePaths(files []string, cwd string) []string {
   298→	var result []string
   299→	for _, file := range files {
