   466→// preTaskFilePrefix is the prefix for pre-task state files
   467→const preTaskFilePrefix = "pre-task-"
   468→
   469→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
   470→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
   471→// When multiple pre-task files exist (nested subagents), returns the most recently
   472→// modified one.
   473→// Works correctly from any subdirectory within the repository.
   474→func FindActivePreTaskFile() (taskToolUseID string, found bool) {
   475→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   476→	if err != nil {
   477→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   478→	}
   479→	entries, err := os.ReadDir(tmpDirAbs)
   480→	if err != nil {
   481→		return "", false
   482→	}
   483→
   484→	var latestFile string
   485→	var latestTime time.Time
   486→
   487→	for _, entry := range entries {
   488→		if entry.IsDir() {
   489→			continue
   490→		}
   491→		name := entry.Name()
   492→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
   493→			continue
   494→		}
   495→
   496→		// Check modification time for nested subagent handling
   497→		info, err := entry.Info()
   498→		if err != nil {
   499→			continue
   500→		}
   501→		if latestFile == "" || info.ModTime().After(latestTime) {
   502→			latestFile = name
   503→			latestTime = info.ModTime()
   504→		}
   505→	}
   506→
   507→	if latestFile == "" {
   508→		return "", false
   509→	}
   510→
   511→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
   512→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
   513→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
   514→	return toolUseID, true
   515→}
