   517→// DetectChangedFiles detects files that have been modified, added, or deleted
   518→// since the last commit (or compared to the index for incremental checkpoints).
   519→// Returns three slices: modified files, new (untracked) files, and deleted files.
   520→// Excludes .entire/ directory from all results.
   521→func DetectChangedFiles() (modified, newFiles, deleted []string, err error) {
   522→	repo, err := openRepository()
   523→	if err != nil {
   524→		return nil, nil, nil, fmt.Errorf("failed to open repository: %w", err)
   525→	}
   526→
   527→	status, err := gitutil.WorktreeStatus(repo)
   528→	if err != nil {
   529→		return nil, nil, nil, fmt.Errorf("failed to get status: %w", err)
   530→	}
   531→
   532→	for file, st := range status {
   533→		// Skip .entire directory
   534→		if paths.IsInfrastructurePath(file) {
   535→			continue
   536→		}
   537→
   538→		// Handle different status codes
   539→		// Worktree status indicates changes not yet staged
   540→		// Staging status indicates changes staged for commit
   541→		switch {
   542→		case st.Worktree == git.Untracked:
   543→			// New untracked file
   544→			newFiles = append(newFiles, file)
   545→		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
   546→			// Deleted file
   547→			deleted = append(deleted, file)
   548→		case st.Worktree == git.Modified || st.Staging == git.Modified ||
   549→			st.Worktree == git.Added || st.Staging == git.Added:
   550→			// Modified or staged file
   551→			modified = append(modified, file)
   552→		}
   553→	}
   554→
   555→	return modified, newFiles, deleted, nil
   556→}
