   558→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
   559→// It counts existing checkpoint files in the task metadata checkpoints directory.
   560→// Returns 1 if no checkpoints exist yet.
   561→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
   562→	// Use the session ID directly as the metadata directory name
   563→	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
   564→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
   565→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
   566→
   567→	entries, err := os.ReadDir(checkpointsDir)
   568→	if err != nil {
   569→		// Directory doesn't exist or can't be read - start at 1
   570→		return 1
   571→	}
   572→
   573→	// Count JSON files (checkpoints)
   574→	count := 0
   575→	for _, entry := range entries {
   576→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
   577→			count++
   578→		}
   579→	}
   580→
   581→	return count + 1
   582→}
