    60→func runDebugAutoCommit(w io.Writer, transcriptPath string) error {
    61→	// Check if we're in a git repository
    62→	repoRoot, err := paths.RepoRoot()
    63→	if err != nil {
    64→		fmt.Fprintln(w, "Not in a git repository")
    65→		return nil //nolint:nilerr // not being in a git repo is expected, not an error for status check
    66→	}
    67→	fmt.Fprintf(w, "Repository: %s\n\n", repoRoot)
    68→
    69→	// Print strategy info
    70→	strat := GetStrategy()
    71→	isAutoCommit := strat.Name() == strategy.StrategyNameAutoCommit
    72→	printStrategyInfo(w, strat, isAutoCommit)
    73→
    74→	// Print session state
    75→	currentSession := printSessionState(w)
    76→
    77→	// Auto-detect transcript if not provided
    78→	if transcriptPath == "" && currentSession != "" {
    79→		detected, detectErr := findTranscriptForSession(currentSession, repoRoot)
    80→		if detectErr != nil {
    81→			fmt.Fprintf(w, "\nCould not auto-detect transcript: %v\n", detectErr)
    82→		} else if detected != "" {
    83→			transcriptPath = detected
    84→			fmt.Fprintf(w, "\nAuto-detected transcript: %s\n", transcriptPath)
    85→		}
    86→	}
    87→
    88→	// Print file changes and get total
    89→	fmt.Fprintln(w, "\n=== File Changes ===")
    90→	var totalChanges int
    91→	if transcriptPath != "" {
    92→		totalChanges = printTranscriptChanges(w, transcriptPath, currentSession, repoRoot)
    93→	} else {
    94→		var err error
    95→		totalChanges, err = printGitStatusChanges(w)
    96→		if err != nil {
    97→			return err
    98→		}
    99→	}
   100→
   101→	// Print decision
   102→	printDecision(w, isAutoCommit, strat.Name(), totalChanges)
   103→
   104→	// Print transcript location help if we couldn't find one
   105→	if transcriptPath == "" {
   106→		printTranscriptHelp(w)
   107→	}
   108→
   109→	return nil
   110→}
