   172→func printTranscriptChanges(w io.Writer, transcriptPath, currentSession, repoRoot string) int {
   173→	fmt.Fprintf(w, "\nParsing transcript: %s\n", transcriptPath)
   174→
   175→	var modifiedFromTranscript, newFiles, deletedFiles []string
   176→
   177→	// Parse transcript
   178→	transcript, err := parseTranscript(transcriptPath)
   179→	if err != nil {
   180→		fmt.Fprintf(w, "  Error parsing transcript: %v\n", err)
   181→	} else {
   182→		modifiedFromTranscript = extractModifiedFiles(transcript)
   183→		fmt.Fprintf(w, "  Found %d modified files in transcript\n", len(modifiedFromTranscript))
   184→	}
   185→	// Compute new and deleted files (single git status call)
   186→	// Load preState only if we have an active session (needed for new file detection)
   187→	var preState *PrePromptState
   188→	if currentSession != "" {
   189→		var loadErr error
   190→		preState, loadErr = LoadPrePromptState(currentSession)
   191→		if loadErr != nil {
   192→			fmt.Fprintf(w, "  Error loading pre-prompt state: %v\n", loadErr)
   193→		}
   194→	}
   195→	// Always call ComputeFileChanges - deleted files don't depend on preState
   196→	newFiles, deletedFiles, err = ComputeFileChanges(preState)
   197→	if err != nil {
   198→		fmt.Fprintf(w, "  Error computing file changes: %v\n", err)
   199→	}
   200→
   201→	// Filter and normalize paths
   202→	modifiedFromTranscript = FilterAndNormalizePaths(modifiedFromTranscript, repoRoot)
   203→	newFiles = FilterAndNormalizePaths(newFiles, repoRoot)
   204→	deletedFiles = FilterAndNormalizePaths(deletedFiles, repoRoot)
   205→
   206→	// Print files
   207→	printFileList(w, "Modified (from transcript)", "M", modifiedFromTranscript)
   208→	printFileList(w, "New files (created during session)", "+", newFiles)
   209→	printFileList(w, "Deleted files", "D", deletedFiles)
   210→
   211→	totalChanges := len(modifiedFromTranscript) + len(newFiles) + len(deletedFiles)
   212→	if totalChanges == 0 {
   213→		fmt.Fprintln(w, "\nNo changes detected from transcript")
   214→	}
   215→
   216→	return totalChanges
   217→}
