   230→	printFileList(w, "Untracked files", "?", untrackedFiles)
   231→	printFileList(w, "Deleted files", "D", deletedFiles)
   232→
   233→	totalChanges := len(modifiedFiles) + len(untrackedFiles) + len(deletedFiles) + len(stagedFiles)
   234→	if totalChanges == 0 {
