   283→// getFileChanges returns the current file changes from git status.
   284→// Returns (modifiedFiles, untrackedFiles, deletedFiles, stagedFiles, error)
   285→func getFileChanges() ([]string, []string, []string, []string, error) {
   286→	repo, err := openRepository()
   287→	if err != nil {
   288→		return nil, nil, nil, nil, err
   289→	}
   290→
   291→	status, err := gitutil.WorktreeStatus(repo)
   292→	if err != nil {
   293→		return nil, nil, nil, nil, fmt.Errorf("getting status: %w", err)
   294→	}
   295→
   296→	var modifiedFiles, untrackedFiles, deletedFiles, stagedFiles []string
   297→
   298→	for file, st := range status {
   299→		// Skip .entire directory
   300→		if paths.IsInfrastructurePath(file) {
   301→			continue
   302→		}
   303→
   304→		// Check staging area first
   305→		switch st.Staging {
   306→		case git.Added, git.Modified:
   307→			stagedFiles = append(stagedFiles, file)
   308→			continue
   309→		case git.Deleted:
   310→			deletedFiles = append(deletedFiles, file)
   311→			continue
   312→		case git.Unmodified, git.Renamed, git.Copied, git.UpdatedButUnmerged, git.Untracked:
   313→			// Fall through to check worktree status
   314→		}
   315→
   316→		// Check worktree status
   317→		switch st.Worktree {
   318→		case git.Modified:
   319→			modifiedFiles = append(modifiedFiles, file)
   320→		case git.Untracked:
   321→			untrackedFiles = append(untrackedFiles, file)
   322→		case git.Deleted:
   323→			deletedFiles = append(deletedFiles, file)
   324→		case git.Unmodified, git.Added, git.Renamed, git.Copied, git.UpdatedButUnmerged:
   325→			// No action needed
   326→		}
   327→	}
   328→
   329→	// Sort for consistent output
   330→	sort.Strings(modifiedFiles)
   331→	sort.Strings(untrackedFiles)
   332→	sort.Strings(deletedFiles)
   333→	sort.Strings(stagedFiles)
   334→
   335→	return modifiedFiles, untrackedFiles, deletedFiles, stagedFiles, nil
   336→}
