   338→// findTranscriptForSession attempts to find the transcript file for a session.
   339→// Returns the path if found, empty string if not found, or error on failure.
   340→func findTranscriptForSession(sessionID, repoRoot string) (string, error) {
   341→	// Try to get agent type from session state
   342→	sessionState, err := strategy.LoadSessionState(sessionID)
   343→	if err != nil {
   344→		return "", fmt.Errorf("failed to load session state: %w", err)
   345→	}
   346→
   347→	var ag agent.Agent
   348→	if sessionState != nil && sessionState.AgentType != "" {
   349→		ag, err = agent.GetByAgentType(sessionState.AgentType)
   350→		if err != nil {
   351→			return "", fmt.Errorf("failed to get agent for type %q: %w", sessionState.AgentType, err)
   352→		}
   353→	} else {
   354→		return "", fmt.Errorf("failed to get agent from sessionID: %s", sessionID)
   355→	}
   356→
   357→	// Get the session directory for this agent
   358→	sessionDir, err := ag.GetSessionDir(repoRoot)
   359→	if err != nil {
   360→		return "", fmt.Errorf("failed to get session dir: %w", err)
   361→	}
   362→
   363→	// Extract the agent-specific session ID (removes date prefix)
   364→	agentSessionID := ag.ExtractAgentSessionID(sessionID)
   365→
   366→	// Build the transcript path
   367→	transcriptPath := filepath.Join(sessionDir, agentSessionID+".jsonl")
   368→
   369→	// Check if it exists
   370→	if _, err := os.Stat(transcriptPath); err != nil {
   371→		if os.IsNotExist(err) {
   372→			return "", nil // Not found, but not an error
   373→		}
   374→		return "", fmt.Errorf("failed to stat transcript: %w", err)
   375→	}
   376→
   377→	return transcriptPath, nil
   378→}
